let
  eval = import /opt/nixpkgs/nixos/lib/eval-config.nix {
    system = "x86_64-linux";
    modules = [ /opt/contract/harness.nix /app/submission/replica.nix ];
  };
  c = eval.config;
in {
  users = builtins.map (n: { name = n; uid = c.users.users.${n}.uid or null; }) (builtins.attrNames c.users.users);
  groups = builtins.map (n: { name = n; gid = c.users.groups.${n}.gid or null; }) (builtins.attrNames c.users.groups);
}
EOF
timeout 600 nix-instantiate --eval --strict --json /tmp/probe/uids.nix 2>&1 | python3 -I -c 'import json,sys; d=json.load(sys.stdin); import collections; u=[(x["name"],x["uid"]) for x in d["users"] if x["uid"] is not None]; g=[(x["name"],x["gid"]) for x in d["groups"] if x["gid"] is not None]; print("uid dups:", [k for k,v in collections.Counter(x for _,x in u).items() if v>1]); print("gid dups:", [k for k,v in collections.Counter(x for _,x in g).items() if v>1]); print([n for n,x in u if x in (33,113)]); print([n for n,x in g if x in (27,117,122,33)])' 2>&1 | tail -8

